// GENEROVANÝ SOUBOR – neupravovat ručně.
//
// Zdroj: Strength Level, veřejná tabulka "By Bodyweight" (kg).
// Na každé stránce cviku jsou zvlášť mužská a ženská tabulka.
// Hodnoty jsou publikované kilogramy pro Beginner, Novice,
// Intermediate, Advanced a Elite (5., 20., 50., 80. a 95. percentil).
//
// Regenerace: dart run tool/generate_rank_standards.dart

/// Tabulka jednoho cviku pro obě pohlaví.
///
/// Každý řádek: [váha těla kg, Beginner, Novice, Intermediate,
/// Advanced, Elite].
class RankTableData {
  const RankTableData({required this.male, required this.female});

  final List<List<int>> male;
  final List<List<int>> female;
}

/// Jeden rankovaný cvik a jeho předloha na Strength Levelu.
class RankStandardEntry {
  const RankStandardEntry({
    required this.name,
    required this.slug,
    this.perHand = false,
    this.aliases = const [],
  });

  final String name;
  final String slug;
  final bool perHand;
  final List<String> aliases;
}

